const d = $input.first().json.data;
const reportDate = new Date(Date.now() + 5.5 * 3600000).toISOString().slice(0, 10);
const SOURCE = { remotive: 'Remotive', arbeitnow: 'Arbeitnow' };

function md(s) {
  return String(s || '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/([\\`*_{}\[\]<>()#|!])/g, '\\$1')
    .trim();
}
function link(url, text) {
  return /^https:\/\/[^\s()<>]+$/.test(String(url || '')) ? '[' + text + '](' + url + ')' : text;
}
function list(a) {
  return a && a.length ? a.map(md).join(', ') : 'none';
}

const top = d.top || [];
const gaps = d.gaps || [];
const lines = [];

lines.push('# Daily career report: ' + reportDate);
lines.push('');
lines.push('New jobs in the last 24 hours: ' + d.new_jobs + '. Jobs scored (last 14 days): ' + d.scored + '. Strong matches (70+): ' + d.strong + '. Moderate (50-69): ' + d.moderate + '.');
if (d.needs_review > 0) {
  lines.push('');
  lines.push(d.needs_review + ' job(s) have rules and AI scores that disagree. Check them yourself.');
}
lines.push('');
lines.push('## Top matches');

if (top.length === 0) {
  lines.push('');
  lines.push('No job scored 50 or more yet. Run the matching workflow, or check the skills in your profile.');
}

top.forEach(function (j, i) {
  const src = SOURCE[j.source] || j.source;
  lines.push('');
  lines.push((i + 1) + '. **' + md(j.title) + '** at ' + md(j.company || 'unknown company') + ' (' + md(j.location || j.work_mode) + '): ' + Math.round(Number(j.final_score)) + '/100' + (j.needs_review ? ' (needs review)' : ''));
  lines.push('   Matched: ' + list(j.matched_skills) + '. Missing: ' + list(j.missing_skills) + '.');
  if (j.reasoning) lines.push('   ' + md(j.reasoning));
  lines.push('   ' + link(j.source_url, 'View on ' + src) + ' (via ' + src + ')');
});

lines.push('');
lines.push('## Skills to learn next');
lines.push('');
if (gaps.length === 0) {
  lines.push('No recurring skill gaps yet.');
} else {
  gaps.forEach(function (g) {
    lines.push('- ' + md(g.skill) + ': missing in ' + g.count + ' job(s)');
  });
}

lines.push('');
lines.push('---');
lines.push('Scores are estimates, not a guarantee of any outcome. Check each job yourself before applying.');
lines.push('Job data: Remotive and Arbeitnow. Each listing links back to its original page.');

return [{
  json: {
    report_date: reportDate,
    title: 'Daily career report: ' + reportDate,
    markdown: lines.join('\n'),
    data: d
  }
}];
